55	// What MHPCO insures each item for, as distinct from what it charges to do so.
56	const INSURANCE_VALUES: Record<string, number> = {
57	  sword: 1000,
58	  amulet: 600,
59	  staff: 800,
60	  potion: 400,
61	  rune: 250,
62	  moonstone: 250,
63	};
64	
65	const BASE_PREMIUMS: Record<string, number> = {
66	  sword: 100,
67	  amulet: 60,
68	  staff: 80,
69	  potion: 40,
70	  rune: 25,
71	  moonstone: 25,
72	};
73	
74	// Percentages are applied as integer arithmetic (× percent ÷ 100) rather than
75	// as a float rate (× 1.1): this keeps intermediate values integral and avoids
76	// binary floating-point error — 100 * 1.1 is 110.00000000000001, but
77	// (100 * 110) / 100 is exact.
78	const ONE_HUNDRED_PERCENT = 100;
79	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
80	const ADMIN_FEE = 5;
81	const LOYALTY_YEARS = 2;
82	const LOYALTY_DISCOUNT_PERCENT = 20;
83	const SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT = 15;
84	const DEDUCTIBLE = 100;
85	const CAP_MULTIPLE = 2;
86	const NO_PAYOUT = 0;
87	const PERILOUS_ENCHANTMENT = 8;
88	const PERILOUS_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
89	const FULL_REIMBURSEMENT_PERCENT = 100;
90	
91	const applyPercent = (amount: number, percent: number): number =>
92	  (amount * percent) / ONE_HUNDRED_PERCENT;
93	
94	const addSurcharge = (amount: number, surchargePercent: number): number =>
95	  applyPercent(amount, ONE_HUNDRED_PERCENT + surchargePercent);
96	
97	const applyDiscount = (amount: number, discountPercent: number): number =>
98	  applyPercent(amount, ONE_HUNDRED_PERCENT - discountPercent);
99	
100	const COMPONENT_TYPES = ["rune", "moonstone"];
101	const BUILDING_BLOCK_SIZE = 3;
102	const BUILDING_BLOCK_BASE_PREMIUM = 60;
103	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
104	
105	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
106	
107	// Risk surcharges are per-item properties of the insured object, each raising
108	// that item's premium by a percentage. They stack multiplicatively: an item
109	// matching two rules is surcharged by the first, then by the second.
110	interface RiskSurcharge {
111	  appliesTo: (item: Item) => boolean;
112	  percent: number;
113	}
114	
115	const HIGH_ENCHANTMENT = 5;
116	const NO_ENCHANTMENT = 0;
117	
118	const RISK_SURCHARGES: RiskSurcharge[] = [
119	  { appliesTo: (item) => item.cursed === true, percent: 50 },
120	  {
121	    appliesTo: (item) => (item.enchantment ?? NO_ENCHANTMENT) >= HIGH_ENCHANTMENT,
122	    percent: 30,
123	  },
124	];
125	
126	const riskAdjustedPremiumOf = (item: Item): number =>
127	  RISK_SURCHARGES.reduce(
128	    (premium, surcharge) =>
129	      surcharge.appliesTo(item) ? addSurcharge(premium, surcharge.percent) : premium,
130	    basePremiumOf(item),
131	  );
132	
133	const sumRiskAdjustedPremiums = (items: Item[]): number =>
134	  items.reduce((total, item) => total + riskAdjustedPremiumOf(item), 0);
135	
136	// Alike components are grouped into building blocks of 3, which carry a
137	// special base premium; the remaining components are priced individually,
138	// risk surcharges and all.
139	// Total over the empty group: no components means no blocks and no remainder.
140	const alikeComponentsPremium = (components: Item[]): number => {
141	  const blockCount = Math.floor(components.length / BUILDING_BLOCK_SIZE);
142	  const remainingComponents = components.slice(blockCount * BUILDING_BLOCK_SIZE);
143	  return (
144	    blockCount * BUILDING_BLOCK_BASE_PREMIUM +
145	    sumRiskAdjustedPremiums(remainingComponents)
146	  );
147	};
148	
149	// Splits items into those matching the predicate and those not, in one pass,
150	// so the rule dividing them is written exactly once.
151	const partition = (
152	  items: Item[],
153	  matches: (item: Item) => boolean,
154	): [Item[], Item[]] =>
155	  items.reduce<[Item[], Item[]]>(
156	    ([matching, rest], item) =>
157	      matches(item) ? [[...matching, item], rest] : [matching, [...rest, item]],
158	    [[], []],
159	  );
160	
161	const groupByType = (items: Item[]): Item[][] => [
162	  ...items
163	    .reduce(
164	      (groups, item) =>
165	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
166	      new Map<string, Item[]>(),
167	    )
168	    .values(),
169	];
170	
171	// Components and main items are priced by different rules, so each group is
172	// totalled separately: components by building block, main items item by item.
173	const componentsPremium = (components: Item[]): number =>
174	  groupByType(components).reduce(
175	    (total, alike) => total + alikeComponentsPremium(alike),
176	    0,
177	  );
178	
179	// What the items alone cost to insure, before any modifier that depends on the
180	// customer or the contract they sit in. This is a premium, not a sum insured:
181	// what MHPCO *charges* for the cover, not what it will *pay out* — an amulet
182	// costs 60 here and is insured for 600 (see insuranceSumOf). Every item is
183	// either a component or a main item — the split is stated once, as a partition,
184	// so the two halves cannot drift apart — and each half is priced by its own
185	// rules.
186	const itemsPremiumOf = (items: Item[]): number => {
187	  const [components, mainItems] = partition(items, isComponent);
188	  return sumRiskAdjustedPremiums(mainItems) + componentsPremium(components);
189	};
190	
191	// Contract-level modifiers adjust the sum insured by the terms of the deal
192	// rather than the nature of the items. Like risk surcharges they stack
193	// multiplicatively, each applying to the result of the one before, so they are
194	// written the same way: a predicate over the contract, and an adjustment.
195	interface Contract {
196	  customer: Customer;
197	  isFirstContract: boolean;
198	}
199	
200	interface ContractModifier {
201	  appliesTo: (contract: Contract) => boolean;
202	  adjust: (amount: number) => number;
203	}
204	
205	// Every contract is priced on one of two standings: a first insurance is
206	// assessed a surcharge, a later one rewarded with a discount. This is a choice,
207	// not two independent rules, so it is written as one — there is no way to
208	// express a contract that gets both or neither.
209	const standingAdjustedPremiumOf = (
210	  amount: number,
211	  { isFirstContract }: Contract,
212	): number =>
213	  isFirstContract
214	    ? addSurcharge(amount, FIRST_INSURANCE_SURCHARGE_PERCENT)
215	    : applyDiscount(amount, SUBSEQUENT_CONTRACT_DISCOUNT_PERCENT);
216	
217	// Modifiers that a contract may or may not earn, on top of its standing. They
218	// stack multiplicatively, each applying to the result of the one before.
219	const CONTRACT_MODIFIERS: ContractModifier[] = [
220	  {
221	    appliesTo: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
222	    adjust: (amount) => applyDiscount(amount, LOYALTY_DISCOUNT_PERCENT),
223	  },
224	];
225	
226	const contractAdjustedPremiumOf = (
227	  itemsPremium: number,
228	  contract: Contract,
229	): number =>
230	  CONTRACT_MODIFIERS.reduce(
231	    (premium, modifier) =>
232	      modifier.appliesTo(contract) ? modifier.adjust(premium) : premium,
233	    standingAdjustedPremiumOf(itemsPremium, contract),
234	  );
235	
236	// Premiums round up in MHPCO's favour, and the flat admin fee is added last
237	// so that no percentage ever applies to it.
238	const billedPremiumOf = (premium: number): number =>
239	  Math.ceil(premium) + ADMIN_FEE;
240	
241	const quote = (step: QuoteStep, contract: Contract): QuoteResult => ({
242	  premium: billedPremiumOf(
243	    contractAdjustedPremiumOf(itemsPremiumOf(step.items), contract),
244	  ),
245	});
246	
247	// The insurance sum is what the items are covered for, and it is the basis of
248	// the payout cap — unrelated to the premium charged for that cover.
249	const insuranceSumOf = (items: Item[]): number =>
250	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
251	
252	// A quote creates a policy, which then absorbs claims: every payout draws down
253	// a cap of twice the insurance sum, so the policy carries state between steps.
254	// The policy keeps the items it covers: a claim is settled by the nature of the
255	// damaged item, so the cover has to be able to look back at what it insured.
256	interface Policy {
257	  remainingCap: number;
258	  items: Item[];
259	}
260	
261	const policyFor = (items: Item[]): Policy => ({
262	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE,
263	  items,
264	});
265	
266	// How much of a damage MHPCO shoulders depends on what was damaged: an item so
267	// heavily enchanted that its own magic invites disaster is met halfway.
268	const reimbursementPercentFor = (item: Item | undefined): number =>
269	  (item?.enchantment ?? NO_ENCHANTMENT) >= PERILOUS_ENCHANTMENT
270	    ? PERILOUS_ENCHANTMENT_REIMBURSEMENT_PERCENT
271	    : FULL_REIMBURSEMENT_PERCENT;
272	
273	const reimbursementFor = (damage: Damage, policy: Policy): number =>
274	  applyPercent(
275	    damage.amount,
276	    reimbursementPercentFor(
277	      policy.items.find((item) => item.type === damage.itemType),
278	    ),
279	  );
280	
281	// An incident's damages are reimbursed one by one, then totalled before the
282	// deductible is taken, so the deductible falls once on the event rather than
283	// once per damaged item.
284	const damageTotalOf = (incident: Incident, policy: Policy): number =>
285	  incident.damages.reduce(
286	    (total, damage) => total + reimbursementFor(damage, policy),
287	    0,
288	  );
289	
290	const claim = (step: ClaimStep, policy: Policy): ClaimResult => {
291	  // The deductible reduces the payout, it never turns it into a charge.
292	  const payout = Math.max(
293	    damageTotalOf(step.incident, policy) - DEDUCTIBLE,
294	    NO_PAYOUT,
295	  );
296	  return { payout, remainingCap: policy.remainingCap - payout };
297	};
298	
299	// Steps are processed in order because each one depends on what came before: a
300	// quote's standing depends on how many contracts precede it, and a claim draws
301	// down the cap its policy has left. Both are carried explicitly as the policies
302	// map rather than mutated in place, so a step's effect on later steps is
303	// visible in what it returns.
304	interface Ledger {
305	  policies: Map<number, Policy>;
306	  results: StepResult[];
307	}
308	
309	const withPolicy = (
310	  policies: Map<number, Policy>,
311	  index: number,
312	  policy: Policy,
313	): Map<number, Policy> => new Map(policies).set(index, policy);
314	
315	const applyStep = (
316	  { policies, results }: Ledger,
317	  step: Step,
318	  index: number,
319	  customer: Customer,
320	): Ledger => {
321	  if (step.op === "quote") {
322	    const contract = { customer, isFirstContract: index === 0 };
323	    return {
324	      policies: withPolicy(policies, index, policyFor(step.items)),
325	      results: [...results, quote(step, contract)],
326	    };
327	  }
328	  const policy = policies.get(step.policy);
329	  if (policy === undefined) {
330	    throw new Error(`Claim refers to unknown policy ${step.policy}`);
331	  }
332	  const result = claim(step, policy);
333	  return {
334	    policies: withPolicy(policies, step.policy, {
335	      ...policy,
336	      remainingCap: result.remainingCap,
337	    }),
338	    results: [...results, result],
339	  };
340	};
341	
342	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
343	  const { results } = steps.reduce<Ledger>(
344	    (ledger, step, index) => applyStep(ledger, step, index, customer),
345	    { policies: new Map(), results: [] },
346	  );
347	  return { results };
348	};
